// Animated diamond kolam — echoes the traditional lattice motif from the
// reference card, drawn dot-by-dot rather than shown as a static graphic.
function KolamDiamond({ size = 64, color = "#E8C878" }) {
  const pts = [];
  const rings = 3;
  for (let r = 1; r <= rings; r++) {
    const n = r * 4;
    for (let i = 0; i < n; i++) {
      const angle = (Math.PI * 2 * i) / n;
      const rx = r * 9 * Math.cos(angle);
      const ry = r * 9 * Math.sin(angle);
      pts.push([rx, ry, r]);
    }
  }
  return (
    <svg width={size} height={size} viewBox="-32 -32 64 64" style={{ overflow: "visible" }}>
      {pts.map(([x, y, r], i) => (
        <motion.circle
          key={i} cx={x} cy={y} r={1.6}
          fill="none" stroke={color} strokeWidth="1"
          initial={{ opacity: 0, scale: 0 }}
          animate={{ opacity: 0.9, scale: 1 }}
          transition={{ duration: 0.5, delay: 0.5 + r * 0.12 + i * 0.012 }}
        />
      ))}
      <motion.path
        d="M0,-26 L26,0 L0,26 L-26,0 Z"
        fill="none" stroke={color} strokeWidth="0.8" opacity="0.6"
        initial={{ pathLength: 0, opacity: 0 }}
        animate={{ pathLength: 1, opacity: 0.6 }}
        transition={{ duration: 1.4, delay: 0.3, ease: "easeInOut" }}
      />
    </svg>
  );
}

// Marigold + mango-leaf toran — the hanging garland strip from the reference
// card, rebuilt as a tileable SVG so it can run the width of the page.
function MarigoldToran({ height = 64, count = 9 }) {
  const items = Array.from({ length: count });
  return (
    <svg width="100%" height={height} viewBox={`0 0 ${count * 60} ${height}`} preserveAspectRatio="none" style={{ display: "block" }}>
      <line x1="0" y1="4" x2={count * 60} y2="4" stroke="#8a6a3a" strokeWidth="1.5" opacity="0.5" />
      {items.map((_, i) => {
        const x = i * 60 + 30;
        const dangle = 18 + (i % 3) * 10;
        return (
          <motion.g key={i}
            initial={{ opacity: 0, y: -8 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: i * 0.05 }}
          >
            {/* string */}
            <line x1={x} y1="4" x2={x} y2={dangle} stroke="#6b8f4e" strokeWidth="1.2" opacity="0.6" />
            {/* mango leaves, alternating sides */}
            {[-1, 1].map((side) => (
              <ellipse key={side} cx={x + side * 5} cy={dangle - 8} rx="4.5" ry="9"
                fill="#5a8a3f" opacity="0.85"
                transform={`rotate(${side * 25} ${x + side * 5} ${dangle - 8})`} />
            ))}
            {/* marigold pom-pom */}
            <motion.circle cx={x} cy={dangle + 6} r="6" fill="#E08A1E"
              animate={{ scale: [1, 1.06, 1] }} transition={{ duration: 3, repeat: Infinity, delay: i * 0.2 }} />
            <circle cx={x} cy={dangle + 6} r="2.6" fill="#F4C05A" />
          </motion.g>
        );
      })}
    </svg>
  );
}

