// Faint repeating kolam lattice used as a card backdrop — a frame of dots
// and diamonds behind the event details, echoing traditional threshold art.
function KolamCardPattern({ color }) {
  const tile = 34;
  const cols = 12;
  const rows = 10;
  const cells = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      cells.push([c * tile + tile / 2, r * tile + tile / 2]);
    }
  }
  return (
    <svg
      width="100%" height="100%" viewBox={`0 0 ${cols * tile} ${rows * tile}`} preserveAspectRatio="xMidYMid slice"
      style={{ position: "absolute", inset: 0, opacity: 0.07 }}
    >
      {cells.map(([x, y], i) => (
        <g key={i}>
          <circle cx={x} cy={y} r="1.4" fill={color} />
          {(i % 3 === 0) && (
            <path d={`M${x},${y - 9} L${x + 9},${y} L${x},${y + 9} L${x - 9},${y} Z`} fill="none" stroke={color} strokeWidth="0.6" />
          )}
        </g>
      ))}
    </svg>
  );
}

