function PhotoSlider() {
  const [index, setIndex] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setIndex((i) => (i + 1) % SLIDER_PHOTOS.length), 3000);
    return () => clearInterval(id);
  }, []);
  const go = (dir) => setIndex((i) => (i + dir + SLIDER_PHOTOS.length) % SLIDER_PHOTOS.length);
  return (
    <div style={{ position: "relative", maxWidth: 320, margin: "0 auto", borderRadius: 20, overflow: "hidden", boxShadow: "0 14px 40px rgba(0,0,0,0.3)" }}>
      <div style={{ position: "relative", width: "100%", aspectRatio: "3/4" }}>
        <AnimatePresence mode="wait">
          <motion.img
            key={index}
            src={SLIDER_PHOTOS[index].src}
            alt={SLIDER_PHOTOS[index].caption}
            initial={{ opacity: 0, scale: 1.05 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.6 }}
            style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }}
          />
        </AnimatePresence>
        <div style={{
          position: "absolute", bottom: 0, left: 0, right: 0, padding: "24px 16px 14px",
          background: "linear-gradient(to top, rgba(0,0,0,0.65), transparent)",
          color: "#F6E4B8", fontFamily: "'Cormorant Garamond', serif", fontStyle: "italic", fontSize: 14,
        }}>
          {SLIDER_PHOTOS[index].caption}
        </div>
        <button onClick={() => go(-1)} style={navBtnStyle("left")}><ChevronLeft size={16} /></button>
        <button onClick={() => go(1)} style={navBtnStyle("right")}><ChevronRight size={16} /></button>
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", gap: 5, padding: "10px 12px", background: "#1F0A14" }}>
        {SLIDER_PHOTOS.map((_, i) => (
          <div key={i} onClick={() => setIndex(i)} style={{
            width: i === index ? 14 : 5, height: 5, borderRadius: 4, cursor: "pointer",
            background: i === index ? "#E8C878" : "rgba(232,200,120,0.35)", transition: "all 0.3s",
          }} />
        ))}
      </div>
    </div>
  );
}

